use super::*;

pub(crate) fn row_to_attestation(r: &rusqlite::Row) -> rusqlite::Result<Attestation> {
    Ok(Attestation {
        specifier: r.get(0)?,
        record_id: r.get(1)?,
        src_hash: r.get(2)?,
        outcome: r.get(3)?,
        session: r.get(4)?,
        n: r.get(5)?,
        reason: r.get(6)?,
        ms_total: r.get(7)?,
        ms_max: r.get(8)?,
        first_at: r.get(9)?,
        last_at: r.get(10)?,
    })
}
